// Auto-generated official UTEA shield logo base64
export const UTEA_LOGO_BASE64 = "";

let cachedBytes: Uint8Array | null = null;
export function getUteaLogoBytes(): Uint8Array {
  if (cachedBytes) return cachedBytes;
  const binary = typeof window !== "undefined" && window.atob ? window.atob(UTEA_LOGO_BASE64) : Buffer.from(UTEA_LOGO_BASE64, "base64").toString("binary");
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  cachedBytes = bytes;
  return bytes;
}

// Direct Data URL for instant, infallible, zero-404 rendering across GitHub Pages & all static hosts
export const UTEA_LOGO_DATA_URL = `data:image/png;base64,${UTEA_LOGO_BASE64}`;
